async function showOnlineMenu(mode='showdown'){if(!releaseReady){toast('Serververbindung wird geprüft');return}try{await ensureGuest()}catch(e){toast(e.message);return}returnLobby();onlineScreen.classList.remove('hidden');$('#onlineMode').value=mode;await refreshRooms()}
async function refreshRooms(){try{const data=await starsRequest('rooms');$('#publicRooms').replaceChildren();if(!data.rooms.length)$('#publicRooms').textContent='Noch keine offenen Räume. Erstelle den ersten Raum.';for(const room of data.rooms){const row=document.createElement('div');row.className='release-row';const text=document.createElement('strong');text.textContent=room.code+' · '+arenaModes[room.mode].title+' · '+room.players+'/'+(room.mode==='showdown'?10:6);const b=document.createElement('button');b.textContent='BEITRETEN';b.onclick=()=>joinOnlineRoom(room.code);row.append(text,b);$('#publicRooms').append(row)}}catch(e){$('#publicRooms').textContent=e.message}}
