$('#createOnlineRoom').onclick=async()=>{try{const data=await starsRequest('room/create',{mode:$('#onlineMode').value,private:$('#privateRoom').checked,fighter:fighterSave.selected});openRoom(data.room)}catch(e){toast(e.message)}};
$('#joinOnlineRoom').onclick=()=>joinOnlineRoom($('#joinCode').value);$('#refreshRooms').onclick=refreshRooms;$('#onlineBack').onclick=()=>returnLobby();$('#onlineMenu').onclick=()=>showOnlineMenu();startMatch=mode=>showOnlineMenu(mode);$('#play').onclick=()=>showOnlineMenu(selected);openFields=()=>showOnlineMenu();for(const b of document.querySelectorAll('[data-menu="events"]'))b.onclick=()=>showOnlineMenu();
