function applyStatus(data){refreshRules(data);if(data.user?.blocked&&!releaseAdmin()){stopOnline();returnLobby()}if(data.maintenance&&!releaseAdmin()){stopOnline();$('#gameScreen').classList.add('hidden')}}
async function restoredStarsAccount(){let data=await starsRequest('status');if(data.user?.role==='admin'){await starsRequest('logout',{});data={...data,user:null,progress:null}}return data}
function finishAccessCheck(){document.documentElement.removeAttribute('data-stars-loading');const startup=$('#starsStartup');if(startup)startup.hidden=true}
async function refreshCatalogForLobby(){try{await loadCatalog();return true}catch(e){netBanner.textContent='● BRAWLER-LISTE NICHT GELADEN';toast('Die Brawler-Liste konnte nicht geladen werden: '+e.message);return false}}
async function initializeStars(){try{const data=await restoredStarsAccount();if(data.maintenance&&data.user?.role!=='admin'){applyStatus(data);finishAccessCheck()}if(data.user&&!data.user.blocked)await acceptAccount(data);else{releaseUser=null;accountKey='guest';accounts.guest={progress:freshProgress('LessiPlayer')};syncProgress(accounts.guest.progress);applyStatus(data);releaseReady=true;finishAccessCheck();if(!data.maintenance)await refreshCatalogForLobby()}finishAccessCheck();const code=new URL(location.href).searchParams.get('room');if(code&&releaseUser&&!data.maintenance){try{const joined=await starsRequest('room/join',{code});openRoom(joined.room)}catch(e){toast('Der Raum konnte nicht geöffnet werden: '+e.message)}}}catch(e){netBanner.textContent='● SERVER NICHT ERREICHBAR';const message=$('#starsStartupMessage');if(message)message.textContent='Der Spielserver ist gerade nicht erreichbar. Du kannst zu Lessing Coach zurückgehen oder erneut prüfen.';const retry=$('#starsStartupRetry');if(retry)retry.hidden=false;toast(e.message)}}
initializeStars();
async function refreshStarsStatus(){
 const data=await starsRequest('status');
 if(releaseUser&&!data.user){
  const hadAccount=registeredPlayer();stopOnline();releaseUser=null;accountKey='guest';
  accounts.guest={progress:freshProgress('Gast')};syncProgress(accounts.guest.progress);returnLobby();
  if(hadAccount)toast('Deine Anmeldung ist abgelaufen. Du kannst als Gast weiterspielen.');
 }else if(releaseUser&&data.user&&releaseUser.name!==data.user.name){await acceptAccount(data)}
 applyStatus(data);
}
setInterval(()=>refreshStarsStatus().catch(()=>{}),10000);

