function resizeOnlineCanvas(){const bounds=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);if(bounds.width&&bounds.height){canvas.width=Math.round(bounds.width*ratio);canvas.height=Math.round(bounds.height*ratio)}}
