const rotateShield=document.createElement('section');rotateShield.className='rotate-shield';rotateShield.setAttribute('role','dialog');rotateShield.setAttribute('aria-modal','true');rotateShield.setAttribute('aria-labelledby','rotateTitle');rotateShield.innerHTML='<div class="rotate-card"><div class="rotate-icon" aria-hidden="true">↻</div><h1 id="rotateTitle">Bitte Handy drehen</h1><p>Lessing Stars wird im Querformat gespielt.<br>Drehe dein Handy seitlich, um fortzufahren.</p><small>Falls sich die Ansicht nicht dreht: Deaktiviere die Ausrichtungssperre im Kontrollzentrum.</small><a href="/">← Zum Terminplaner</a></div>';document.body.append(rotateShield);
function updateOrientationGate(){const blocked=portraitPlayBlocked();rotateShield.hidden=!blocked;document.querySelector('main.lobby').inert=blocked;releaseNav.inert=blocked;if(blocked){gameKeys.clear();networkFire=false;networkSuper=false;manualAim=false;stick={dx:0,dy:0};stickPad.firstChild.style.transform='';close()}else resizeOnlineCanvas()}
window.addEventListener('resize',updateOrientationGate);window.addEventListener('orientationchange',updateOrientationGate);window.visualViewport?.addEventListener('resize',updateOrientationGate);document.addEventListener('keydown',e=>{if(portraitPlayBlocked()){e.preventDefault();e.stopImmediatePropagation()}},true);updateOrientationGate();

