const cleanFighterRender=renderFighters;renderFighters=function(){if(!fighters.some(f=>f.id===previewFighter))previewFighter=fighterSave.selected||fighters[0]?.id;cleanFighterRender();for(const b of document.querySelectorAll('[data-fighter]')){const f=fighters.find(f=>f.id===b.dataset.fighter);b.classList.toggle('locked',!collection.brawlers.includes(f.id));b.querySelector('.meter').textContent=f.id===fighterSave.selected?'AUSGEWÄHLT ✓':collection.brawlers.includes(f.id)?'ANSEHEN':'GESPERRT';b.querySelector('.meta').setAttribute('title',f.name)}if(sortFighters==='normal'){const grid=$('#fighterGrid');[...grid.children].sort((a,b)=>a.getAttribute('aria-label').localeCompare(b.getAttribute('aria-label'),'de')).forEach(b=>grid.append(b))}};
