// Safari may lack createImageBitmap, and large encoded photos exceed the API limit.
async function prepareFighterImage(file){
 let picture,objectUrl;
 try{
  if(typeof createImageBitmap==='function')picture=await createImageBitmap(file);
  else{objectUrl=URL.createObjectURL(file);picture=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Bild konnte nicht geladen werden.'));image.src=objectUrl})}
  const c=document.createElement('canvas'),w=picture.width||picture.naturalWidth,h=picture.height||picture.naturalHeight;
  for(let limit=512;limit>=64;limit=Math.floor(limit*.75)){
   const ratio=Math.min(1,limit/Math.max(w,h));c.width=Math.max(1,Math.round(w*ratio));c.height=Math.max(1,Math.round(h*ratio));c.getContext('2d').drawImage(picture,0,0,c.width,c.height);
   const encoded=c.toDataURL('image/webp',.8);if(encoded.length<=220000)return encoded;
  }
  throw Error('Dieses Bild ist zu groß. Bitte ein kleineres Figurenbild auswählen.');
 }finally{picture?.close?.();if(objectUrl)URL.revokeObjectURL(objectUrl)}
}
$('#editorUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('#editorStatus').textContent='Bild wird vorbereitet …';try{if(file.size>6000000)throw Error('Bitte ein Bild unter 6 MB auswählen.');editorImage=await prepareFighterImage(file);const image=new Image();image.src=editorImage;image.alt='Neue Figur';$('#editorPreview').replaceChildren(image);$('#editorStatus').textContent='Bild bereit. Jetzt Brawler speichern.'}catch(error){$('#editorStatus').textContent=error.message}};
